function initLang(){
 const switcher=document.getElementById('languageSwitcher'),current=document.getElementById('langCurrent'),menu=document.getElementById('langMenu'),label=document.getElementById('langCurrentLabel');
 if(!switcher||!current||!menu||!label)return;
 const close=()=>{menu.hidden=true;current.setAttribute('aria-expanded','false')};
 current.addEventListener('click',e=>{e.stopPropagation();menu.hidden=!menu.hidden;current.setAttribute('aria-expanded',String(!menu.hidden))});
 menu.querySelectorAll('.lang-btn').forEach(b=>b.addEventListener('click',()=>{applyLang(b.dataset.lang);close()}));
 document.addEventListener('click',e=>{if(!switcher.contains(e.target))close()});
 document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
 applyLang(currentLang);
}
function applyLang(lang){
 if(!LANGS[lang])lang='lv';currentLang=lang;localStorage.setItem('sb_lang',lang);document.documentElement.lang=lang;if(LANGS[lang].pageTitle)document.title=LANGS[lang].pageTitle;const meta=document.querySelector('meta[name=description]');if(meta&&LANGS[lang].pageDescription)meta.content=LANGS[lang].pageDescription;
 const p=LANGS[lang];const m={'finder':p.finder,'map':p.map,'shop':p.shop,'messages':p.messages,'about':p.about,'signin':p.signin,'signup':p.signup,'hero-eyebrow':p.heroEyebrow,'hero-desc':p.heroDesc};
 Object.entries(m).forEach(([k,v])=>document.querySelectorAll(`[data-langtext="${k}"]`).forEach(e=>e.textContent=v));
 const label=document.getElementById('langCurrentLabel');if(label)label.textContent=lang.toUpperCase();document.querySelectorAll('.lang-btn').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));
 const hero=document.querySelector('.hero-slogan');if(hero)hero.innerHTML=lang==='en'?'Training alone is harder.<br><em>Together is easier.</em>':lang==='ru'?'Тренироваться одному сложнее.<br><em>Вместе легче.</em>':'Vienatnē trenēties ir grūtāk.<br><em>Kopā ir vieglāk.</em>';
 translateStatic();
 renderHeroStats();renderShop();findPartners();renderCart();renderCartBadge();renderMap();initDM();const legal=document.getElementById('legalModal');if(legal?.classList.contains('open')&&legal.dataset.key)openLegal(legal.dataset.key);if(window.__bookingVenue&&document.getElementById('bookingModal')?.classList.contains('open'))openBooking(window.__bookingVenue);
}

function genPartners(sport,city,level){
 const names=['Kārlis','Elīna','Roberts','Anna','Jānis','Laura','Mareks','Dita','Artūrs','Sabīne','Ralfs','Zane','Emīls','Līga','Toms'];
 const sports=sport?[sport]:['Teniss','Padel','Basketbols','Futbols','Skriešana','Velosports','Peldēšana','Bokss / MMA','Volejbols','Hokejs','Disku golfs','Fitnesa zāle','Badmintons','Galda teniss','Klinšu kāpšana','Džudo','Piklbols','Vieglatlētika','Joga','Golfs'];
 const cities=city?[city]:[...new Set(VENUES.map(v=>v.city))]; const levels=level?[level]:['Iesācējs','Vidējs','Pieredzējis','Profesionālis']; const seen=new Set();const out=[];for(let i=0;out.length<6&&i<100;i++){const name=names[Math.floor(Math.random()*names.length)];if(seen.has(name))continue;seen.add(name);out.push({name,sport:sports[Math.floor(Math.random()*sports.length)],city:cities[Math.floor(Math.random()*cities.length)],level:levels[Math.floor(Math.random()*levels.length)]})}return out
}
function findPartners(){const list=genPartners(document.getElementById('fSport').value,document.getElementById('fCity').value,document.getElementById('fLevel').value);document.getElementById('partnerResults').innerHTML=list.map(p=>`<article class="partner-card" data-sport="${esc(p.sport)}" data-city="${esc(p.city)}" data-level="${esc(p.level)}"><div class="partner-avatar"><span>${esc(p.name[0])}</span></div><div><strong>${esc(p.name)}</strong><small>${esc(sportLabel(p.sport))} · ${esc(p.city)}</small><span>${esc(p.level)}</span></div><button type="button" class="partner-action" aria-label="${esc(t('send'))} ${esc(p.name)}" title="${esc(t('send'))}" onclick="goMessages('${esc(p.name)}')">→</button></article>`).join('')}
function goMessages(name){
 const card=[...document.querySelectorAll('.partner-card')].find(el=>norm(el.querySelector('strong')?.textContent||'')===norm(name));
 const sport=card?.dataset.sport||'Teniss';
 const city=card?.dataset.city||'Rīga';
 const level=card?.dataset.level||'Vidējs';
 let idx=DM_CONTACTS.findIndex(c=>norm(c.name)===norm(name));
 if(idx<0){
   DM_CONTACTS.push({name,sport,city,level});
   DM_HISTORY.push([]);
   saveDM();
   idx=DM_CONTACTS.length-1;
 }
 activeDM=idx;
 document.getElementById('messages')?.scrollIntoView({behavior:'smooth',block:'start'});
 setTimeout(()=>initDM(),180);
}

function initDM(){
 const list=document.getElementById('chatList');if(!list)return;
 list.innerHTML=DM_CONTACTS.map((c,i)=>{const last=DM_HISTORY[i]?.[DM_HISTORY[i].length-1]?.text||t('noNew');return `<button class="chat-list-item ${i===activeDM?'active':''}" onclick="openDM(${i})"><div class="partner-avatar">${esc(c.name[0])}</div><div class="chat-contact"><div><strong>${esc(c.name)}</strong><span class="online-dot"></span></div><small>${esc(sportLabel(c.sport))} · ${esc(c.city)}</small><p>${esc(last).slice(0,48)}${last.length>48?'…':''}</p></div><span class="chat-chevron">›</span></button>`}).join('');
 openDM(Math.min(Math.max(Number(activeDM)||0,0),DM_CONTACTS.length-1),false);
}
function openDM(i,seed=true){
 activeDM=Number(i)||0;const c=DM_CONTACTS[activeDM];
 document.querySelectorAll('.chat-list-item').forEach((x,idx)=>x.classList.toggle('active',idx===activeDM));
 const h=document.getElementById('chatHead');
 if(h)h.innerHTML=`<div class="chat-profile"><div class="partner-avatar large">${esc(c.name[0])}</div><div><strong>${esc(c.name)}</strong><span>${esc(sportLabel(c.sport))} · ${esc(c.city)} · ${esc(c.level)}</span></div><div class="chat-head-actions"><button type="button" onclick="go('map')">${t('findPlace')}</button><button type="button" onclick="go('map');setTimeout(()=>{const v=VENUES.find(x=>norm(x.city)===norm('${esc(c.city)}')&&x.bookable===true);if(v)openBooking(v)},250)">${t('book')}</button><button type="button" class="chat-reset" onclick="resetDMHistory()">${t('restart')}</button></div></div>`;
 if(seed&&!DM_HISTORY[activeDM].length){DM_HISTORY[activeDM].push({from:'them',text:currentLang==='en'?`Hi! I'm looking for a ${sportLabel(c.sport).toLowerCase()} training partner in ${c.city}. When would suit you?`:currentLang==='ru'?`Привет! Я ищу партнёра для ${sportLabel(c.sport).toLowerCase()} в ${c.city}. Когда тебе удобно?`:`Sveiks! Es meklēju partneri ${sportLabel(c.sport).toLowerCase()} treniņam ${c.city}. Kad tev būtu ērti?`},{from:'them',text:currentLang==='en'?'If you like, we can find a suitable place on the map and agree on a time.':currentLang==='ru'?'Можем сразу найти подходящее место на карте и договориться о времени.':'Ja gribi, varam uzreiz atrast piemērotu vietu Kartē un vienoties par laiku.'});saveDM()}
 renderDM();
}
function resetDMHistory(){if(!DM_HISTORY[activeDM])return;DM_HISTORY[activeDM]=[];saveDM();openDM(activeDM);toast(currentLang==='en'?'Conversation reset.':currentLang==='ru'?'Переписка сброшена.':'Saruna atiestatīta.');}
function saveDM(){safeSet(DM_STORE_KEY,DM_HISTORY)}
function renderDM(){const b=document.getElementById('chatBody');if(!b)return;b.innerHTML=DM_HISTORY[activeDM].map(m=>`<div class="message-row ${m.from==='me'?'me':'them'}"><div class="bubble ${m.from==='me'?'me':'them'}">${esc(m.text)}<time>${m.from==='me'?(currentLang==='en'?'Sent':currentLang==='ru'?'Отправлено':'Nosūtīts'):t('today')}</time></div></div>`).join('');b.scrollTop=b.scrollHeight}
function dmReply(c,text){
 const raw=norm(text);
 const sport=sportLabel(c.sport).toLowerCase();
 if(/sveik|cau|hello|hey|привет/.test(raw))return currentLang==='en'?'Hi! Great to hear from you. What would you like to arrange?':currentLang==='ru'?'Привет! Рад тебя слышать. Что хочешь обсудить?':'Sveiks! Prieks dzirdēt. Ko gribi sarunāt?';
 if(/laik|kad|rīt|rit|šodien|sodien|nedel|week|когда|завтра|сегодня/.test(raw))return currentLang==='en'?`Weekday evenings after 18:00 usually work for me. We can meet around ${c.city} for ${sport}.`:currentLang==='ru'?`Мне обычно удобно по вечерам после 18:00. Можем встретиться в ${c.city} и потренироваться: ${sport}.`:`Man parasti der darba dienu vakari pēc 18:00. ${c.sport} varam sarunāt ${c.city} pusē.`;
 if(/vieta|kur|zāl|lauk|court|gym|где|мест/.test(raw))return currentLang==='en'?`Open the Map section to see ${c.city} venues. You can open a place and book it where available.`:currentLang==='ru'?`Откройте раздел «Карта», чтобы увидеть места в городе ${c.city}. Где доступно, можно открыть место и забронировать.`:`Apskati Kartes sadaļā ${c.city} vietas. Vari atvērt konkrēto vietu un nospiest “Rezervēt”.`;
 if(/cena|maks|eur|€|сколько|цена/.test(raw))return currentLang==='en'?'Let’s check the specific venue price on the Map. If we book together, we can split the cost.':currentLang==='ru'?'Давай посмотрим цену конкретного места на карте. Если забронируем вместе, можно разделить стоимость.':'Paskatāmies konkrētās vietas cenu Kartē. Ja izvēlamies laukumu kopā, varam sadalīt izmaksas.';
 if(/līmen|limen|pieredz|level|уров/.test(raw))return currentLang==='en'?`My level is ${c.level.toLowerCase()}. We can adapt the session to a level that works for both of us.`:currentLang==='ru'?`Мой уровень — ${c.level.toLowerCase()}. Можем подстроить тренировку под удобный для нас уровень.`:`Mans līmenis ir ${c.level.toLowerCase()}. Droši varam pielāgot treniņu līmenim, kas abiem der.`;
 if(/rezerv|booking|book|брони/.test(raw))return currentLang==='en'?'Yes. Choose a venue on the Map, date and time, and we can create a demo booking.':currentLang==='ru'?'Да. Выбираем место на карте, дату и время — и можем создать демо-бронирование.':'Jā. Izvēlamies vietu Kartē, datumu un laiku, un varam izveidot demo rezervāciju.';
 return currentLang==='en'?`Sounds good. I’m around ${c.city} and looking for a ${sport} partner. Tell me a day, time or place that works for you.`:currentLang==='ru'?`Звучит хорошо. Я в районе ${c.city} и ищу партнёра по ${sport}. Напиши день, время или место.`:`Skan labi. Esmu ${c.city} pusē un meklēju ${c.sport.toLowerCase()} partneri. Pasaki dienu, laiku vai vietu, kas tev der.`;
}
function sendDM(e){e.preventDefault();const input=document.getElementById('chatInput'),text=input.value.trim();if(!text)return;const idx=activeDM;DM_HISTORY[idx].push({from:'me',text});saveDM();renderDM();input.value='';setTimeout(()=>{DM_HISTORY[idx].push({from:'them',text:dmReply(DM_CONTACTS[idx],text)});saveDM();if(activeDM===idx){renderDM();initDM()}},650)}

function bestProduct(q){
 const n=norm(q);
 const aliases={
  'casall':['casall','yoga','mat','balance','4mm','yoga mat balance','casall yoga mat'],
  'wilson pro staff':['prostaff','pro staff','wilson','97','v14'],
  'head radical':['head','radical','mp'],
  'technical viper':['babolat','technical','viper'],
  'adipower':['adidas','adipower','multiweight'],
  'garmin':['garmin','forerunner','265'],
  'trek marlin':['trek','marlin','bike','velosipeds'],
  'bauer':['bauer','supreme','m5','skates','slidas'],
  'ccm tacks':['ccm','tacks','as580','slidas'],
  'everlast':['everlast','nevatear','boksa','maiss'],
  'buzzz':['discraft','buzzz']
 };
 let best=null,bestScore=0;
 for(const p of PRODUCTS){
  const full=norm(`${p.name} ${p.brand} ${p.id} ${p.desc}`);
  const tokens=n.split(' ').filter(x=>x.length>=2);
  let score=0;
  tokens.forEach(t=>{if(full.includes(t))score+=t.length>=5?5:3});
  if(n.includes(norm(p.brand)))score+=8;
  Object.values(aliases).forEach(a=>{const hits=a.filter(x=>n.includes(norm(x))).length;if(hits>=2&&a.some(x=>full.includes(norm(x))))score+=hits*4});
  if(score>bestScore){best=p;bestScore=score}
 }
 return bestScore>=7?best:null;
}
function venueMatches(q){const n=norm(q);let list=VENUES.slice();const cities=[...new Set(VENUES.map(v=>v.city))];const city=cities.find(c=>n.includes(norm(c)));if(city)list=list.filter(v=>norm(v.city)===norm(city));const sports=[['tenis','tenis'],['padel','padel'],['basketbol','basketbol'],['futbol','futbol'],['hokej','hokej'],['volejbol','volejbol'],['bokss','bokss'],['peld','peldesana'],['skries','skriesana'],['velo','velosports'],['fitness','fitnesa'],['disku','disku golfs'],['badminton','badminton'],['galda tenis','galda teniss'],['kapsan','klinšu kāpšana'],['džudo','džudo'],['piklbol','piklbols'],['vieglatlet','vieglatlētika'],['joga','joga'],['golfs','golfs'],['ekstrem','ekstrem']];const sp=sports.find(x=>n.includes(x[0]));if(sp)list=list.filter(v=>norm(v.sport).includes(norm(sp[1])));return list.sort((a,b)=>(b.rating||0)-(a.rating||0))}
function botAnswer(q){
 const n=norm(q);
 if(!n)return 'Uzdod konkrētu jautājumu, piemēram: “Cik maksā Casall Yoga Mat?”';
 if(/^(sveik|cau|labdien|hello|hey)/.test(n))return 'Sveiks! Es varu atrast konkrētu preci, cenu, sporta vietu, piegādes opciju vai palīdzēt ar rezervāciju. Piemēram: “Cik maksā Casall Yoga Mat?”';
 const p=bestProduct(n);
 if(p){
   if(/cik|cena|maks|eur|price|cost/.test(n))return `${p.name} pašreizējā kataloga cena ir ${euro(p.price)}. ${p.old?`Iepriekš ${euro(p.old)}.`:''}`;
   return `${p.name}: ${p.desc} Cena: ${euro(p.price)}.`;
 }
 if(/lēt|let|cheap|budzet|zem.*eur/.test(n)){const a=[...PRODUCTS].sort((a,b)=>a.price-b.price).slice(0,5);return 'Lētākās preces: '+a.map(p=>`${p.name} - ${euro(p.price)}`).join('; ')+'.'}
 if(/karte|vieta|zāl|lauk|venue|sporta/.test(n)){const a=venueMatches(n);return a.length?`Atradu ${a.length} vietas. Labākie rezultāti: ${a.slice(0,6).map(v=>`${v.name} (${v.city}, ${v.price})`).join('; ')}. Atsauksmju skaitļi tiek rādīti tikai tad, ja tie ir verificēti.`:'Šim meklējumam vietu neatradu.'}
 if(/partner|biedr|treniņ|tren/.test(n))return 'Atrast biedru sadaļā izvēlies sporta veidu, pilsētu un līmeni. Pēc tam vari sākt sarunu Ziņu sadaļā.';
 if(/groz|cart/.test(n)){const count=cartCount();return count?`Grozā ir ${count} preces par ${euro(cartSubtotal())} bez piegādes.`:'Grozs ir tukšs.'}
 if(/omniva|pakomat|piegad|kurjer|delivery/.test(n))return 'Omniva pakomāts maksā 2,99 €, kurjers līdz durvīm 4,99 €. Omniva izvēlē vispirms izvēlies pilsētu un pēc tam konkrētu pakomātu. Veikala izņemšana nav pieejama.';
 if(/skaidr|cash|nauda/.test(n))return 'Skaidra nauda ir pieejama tikai kurjera piegādei. Omniva izmantojam tiešsaistes apmaksu.';
 if(/stripe|apmaks|maksaj|payment|karte/.test(n))return 'Tiešsaistes apmaksa notiek Stripe Checkout. Pēc mūsu pārbaudes Stripe parāda kontam pieejamos maksājumu veidus.';
 if(/clerk|registr|ienakt|login|sign in|account|captcha|google/.test(n))return 'Konts izmanto Clerk. Reālai autentifikācijai atver vietni caur HTTPS vai localhost, nevis file://. Google pieteikšanās prasa, lai Google savienojums būtu aktivizēts Clerk Dashboard un atļautais domēns būtu pareizi iestatīts.';
 if(/rezerv|booking/.test(n))return 'Kartē nospied “Rezervēt” pie konkrētās vietas. Vari izvēlēties datumu, laiku un spēlētāju skaitu. Šobrīd tā ir demo rezervācijas plūsma, ko vēlāk var savienot ar kluba rezervācijas API.';
 if(/ziņ|chat|sarakst|message/.test(n))return 'Ziņu sadaļā vari izvēlēties partneri, rakstīt ziņu un izmantot ātrās darbības vietas vai rezervācijas atrašanai.';
 return 'Varu atbildēt par konkrētām precēm un cenām, sporta vietām, karti, piegādi, Stripe, kontu, rezervācijām un Ziņām. Uzdod vienu konkrētu jautājumu.';
}
function toggleChatbot(){const p=document.getElementById('chatbotPanel'),o=!p.classList.contains('open');p.classList.toggle('open',o);if(o&&!p.dataset.greeted){addBot(currentLang==='en'?'Hi! I know the page data. Ask something like “How much is the Casall Yoga Mat?”':currentLang==='ru'?'Привет! Я знаю данные страницы. Спроси, например: «Сколько стоит Casall Yoga Mat?»':'Sveiks! Es zinu lapas datus. Pajautā, piemēram, “Cik maksā Casall Yoga Mat?”');p.dataset.greeted='1'}}
function closeChatbotPanel(){document.getElementById('chatbotPanel').classList.remove('open')}
function addBot(t,m=false){const b=document.getElementById('chatbotBody');const d=document.createElement('div');d.className=`bubble ${m?'me':'them'}`;d.textContent=t;b.appendChild(d);b.scrollTop=b.scrollHeight}
function sendBotMsg(e){e.preventDefault();const i=document.getElementById('chatbotInput'),q=i.value.trim();if(!q)return;addBot(q,true);i.value='';setTimeout(()=>addBot(botAnswer(q)),220)}

function go(id){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
const LEGAL_CONTENT={
 terms:{eyebrow:'Pirkumi',title:'Pirkumu noteikumi',html:`<p><strong>Pirms publicēšanas jāievieto faktiskā pārdevēja informācija:</strong> juridiskais nosaukums, reģistrācijas numurs, juridiskā adrese, e-pasts un tālrunis.</p><h4>Pasūtīšana</h4><p>Pirms pasūtījuma pabeigšanas pircējs redz preci, cenu, izvēlēto piegādes veidu un pilno summu. Pēc pasūtījuma Stripe gadījumā apmaksa tiek apstrādāta drošajā Stripe Checkout vidē.</p><h4>Atteikuma tiesības</h4><p>Piemērojamajiem distances pirkumiem patērētājam parasti ir 14 dienu atteikuma tiesības no preces saņemšanas dienas. Pārdevējam jānodrošina arī informācija par atteikuma kārtību un atteikuma veidlapa.</p><h4>Izņēmumi</h4><p>Atteikuma tiesībām ir likumā noteikti izņēmumi, piemēram, noteiktām precēm, kas izgatavotas pēc pasūtījuma vai kuru īpašības pēc atvēršanas nepieļauj atgriešanu.</p>`},
 delivery:{eyebrow:'Piegāde',title:'Piegāde un atgriešana',html:`<h4>Piegādes veidi</h4><ul><li>Omniva pakomāts - 2,99 €.</li><li>Kurjers līdz durvīm - 4,99 €.</li></ul><p>SportaBiedrs.lv šobrīd nav atsevišķas fiziskas veikala adreses, tāpēc veikala izņemšana nav pieejama.</p><h4>Piegādes termiņš</h4><p>Pasūtījuma laikā tiek norādīts sagaidāmais piegādes veids un termiņš. Ja nav panākta cita vienošanās, distances pirkumam piemērojamie noteikumi paredz preces piegādi ne vēlāk kā 30 dienu laikā.</p><h4>Atgriešana</h4><p>Patērētājam pēc atteikuma paziņošanas prece parasti jānosūta atpakaļ 14 dienu laikā. Pārdevējam nauda jāatmaksā 14 dienu laikā no atteikuma saņemšanas, taču tiesību aktos paredzētajos gadījumos atmaksu var aizturēt līdz preces saņemšanai atpakaļ vai nosūtīšanas apliecinājumam.</p>`},
 privacy:{eyebrow:'Privātums',title:'Privātuma politika',html:`<p>Šis prototips var apstrādāt konta, saziņas, pasūtījuma, piegādes un tehniskos datus, kas nepieciešami pakalpojuma nodrošināšanai.</p><h4>Pakalpojumu sniedzēji</h4><p>Autentifikācijai tiek izmantots Clerk, bet tiešsaistes maksājumiem Stripe. Pirms publiskas palaišanas jānorāda faktiskie datu pārziņa rekvizīti, apstrādes tiesiskais pamats, glabāšanas termiņi un datu subjektu kontaktpunkts.</p><h4>Tavas tiesības</h4><p>Par piekļuvi, labošanu, dzēšanu vai citiem datu aizsardzības jautājumiem jābūt norādītam faktiskā pārziņa kontaktam.</p>`},
 cookies:{eyebrow:'Privātums',title:'Sīkdatņu politika',html:`<p>Nepieciešamās sīkdatnes nodrošina vietnes darbību, piemēram, grozu, valodu, sesijas un drošības funkcijas. Neobligātās statistikas sīkdatnes drīkst ieslēgt tikai pēc lietotāja izvēles.</p><h4>Izvēles maiņa</h4><p>Sīkdatņu izvēli var mainīt vietnes kājenē. Pirms publiskas palaišanas jāpielāgo kategorijas faktiskajiem analītikas un mārketinga rīkiem.</p>`}
};
const LEGAL_CONTENT_I18N={
 en:{terms:{eyebrow:'Purchases',title:'Purchase terms',html:`<p><strong>Before launch, the seller’s real business details must be added:</strong> legal name, registration number, legal address, email and phone.</p><h4>Ordering</h4><p>Before completing an order, the buyer sees the product, price, delivery method and total. For Stripe orders, payment is processed in Stripe Checkout.</p><h4>Withdrawal rights</h4><p>For applicable distance purchases, consumers generally have a 14-day withdrawal period from receipt. The seller must provide the withdrawal procedure and form.</p><h4>Exceptions</h4><p>Withdrawal rights have statutory exceptions, including certain made-to-order goods or goods whose nature prevents return after opening.</p>`},delivery:{eyebrow:'Delivery',title:'Delivery & returns',html:`<h4>Delivery methods</h4><ul><li>Omniva parcel machine — €2.99.</li><li>Courier to your door — €4.99.</li></ul><p>SportaBiedrs.lv currently has no physical shop address, so store pickup is not available.</p><h4>Delivery time</h4><p>The expected delivery method and timing are shown during the order. Unless otherwise agreed, applicable distance-sale rules generally require delivery within 30 days.</p><h4>Returns</h4><p>After withdrawal, the consumer generally sends the goods back within 14 days. Refunds are generally due within 14 days, subject to statutory conditions.</p>`},privacy:{eyebrow:'Privacy',title:'Privacy policy',html:`<p>This prototype may process account, messaging, order, delivery and technical data needed to provide the service.</p><h4>Service providers</h4><p>Clerk is used for authentication and Stripe for online payments. Before public launch, the real controller details, legal basis, retention periods and data-subject contact must be added.</p><h4>Your rights</h4><p>A real controller contact must be provided for requests about access, correction, deletion and other data-protection rights.</p>`},cookies:{eyebrow:'Privacy',title:'Cookie policy',html:`<p>Necessary storage supports functions such as the cart, language, sessions and security. Optional analytics should only be enabled after user choice.</p><h4>Changing your choice</h4><p>Cookie choices can be changed from the footer. Before launch, the categories should be matched to the actual analytics and marketing tools.</p>`}},
 ru:{terms:{eyebrow:'Покупки',title:'Условия покупки',html:`<p><strong>До запуска необходимо указать реальные данные продавца:</strong> юридическое название, регистрационный номер, адрес, e-mail и телефон.</p><h4>Заказ</h4><p>Перед оформлением заказа покупатель видит товар, цену, способ доставки и итоговую сумму. При оплате Stripe обработка выполняется в Stripe Checkout.</p><h4>Право на отказ</h4><p>Для применимых дистанционных покупок обычно действует 14-дневный срок отказа с момента получения товара. Продавец должен предоставить порядок отказа и форму.</p><h4>Исключения</h4><p>Право на отказ имеет предусмотренные законом исключения, в том числе для некоторых товаров, изготовленных на заказ.</p>`},delivery:{eyebrow:'Доставка',title:'Доставка и возврат',html:`<h4>Способы доставки</h4><ul><li>Постамат Omniva — 2,99 €.</li><li>Курьер до двери — 4,99 €.</li></ul><p>У SportaBiedrs.lv сейчас нет отдельного физического магазина, поэтому самовывоз недоступен.</p><h4>Срок доставки</h4><p>Способ и ожидаемый срок доставки показываются при оформлении. Если не согласовано иное, применимые правила дистанционной торговли обычно предусматривают доставку не позднее 30 дней.</p><h4>Возврат</h4><p>После уведомления об отказе товар обычно необходимо отправить обратно в течение 14 дней. Возврат средств обычно производится в течение 14 дней с учётом предусмотренных законом условий.</p>`},privacy:{eyebrow:'Конфиденциальность',title:'Политика конфиденциальности',html:`<p>Прототип может обрабатывать данные аккаунта, переписки, заказа, доставки и технические данные, необходимые для работы сервиса.</p><h4>Поставщики</h4><p>Clerk используется для аутентификации, Stripe — для онлайн-платежей. До публичного запуска необходимо добавить реальные данные контролёра, правовое основание, сроки хранения и контакт для запросов.</p><h4>Ваши права</h4><p>Должен быть указан реальный контакт для запросов о доступе, исправлении, удалении и других правах субъекта данных.</p>`},cookies:{eyebrow:'Конфиденциальность',title:'Политика cookie',html:`<p>Необходимое локальное хранение поддерживает корзину, язык, сессии и функции безопасности. Необязательную аналитику следует включать только после выбора пользователя.</p><h4>Изменение выбора</h4><p>Настройки cookie можно изменить в нижней части сайта. Перед запуском категории должны соответствовать фактическим инструментам аналитики и маркетинга.</p>`}}
};
function openLegal(key){const x=(LEGAL_CONTENT_I18N[currentLang]&&LEGAL_CONTENT_I18N[currentLang][key])||LEGAL_CONTENT[key];if(!x)return;document.getElementById('legalModal').dataset.key=key;document.getElementById('legalEyebrow').textContent=x.eyebrow;document.getElementById('legalTitle').textContent=x.title;document.getElementById('legalBody').innerHTML=x.html;document.getElementById('legalModal').classList.add('open')}

async function openCheckout(){if(!CART.length){toast(currentLang==='en'?'Cart is empty.':currentLang==='ru'?'Корзина пуста.':'Grozs ir tukšs.');return}toggleCart(false);clearCheckoutError();document.getElementById('checkoutModal').classList.add('open');document.getElementById('checkoutStep1').hidden=false;document.getElementById('checkoutStep2').hidden=true;document.getElementById('checkoutStep3').hidden=true;populateLockerCities();updateCheckoutFields();renderCheckoutMini();loadOmnivaLocations().catch(()=>{})}
function closeModal(id){document.getElementById(id)?.classList.remove('open')}
function setDelivery(v){document.getElementById('coDelivery').value=v;updateCheckoutFields()}
function renderLockerCityOptions(){const city=document.getElementById('coLockerCity');if(!city)return;const current=city.value;city.innerHTML='';Object.keys(OMNIVA_LOCKERS).sort((a,b)=>a.localeCompare(b,'lv')).forEach(c=>{const o=document.createElement('option');o.value=c;o.textContent=c;city.appendChild(o)});if(current&&OMNIVA_LOCKERS[current])city.value=current;else if(city.options.length)city.selectedIndex=0;populateLockerOptions()}
function populateLockerCities(){renderLockerCityOptions()}
function populateLockerOptions(){const city=document.getElementById('coLockerCity')?.value||Object.keys(OMNIVA_LOCKERS)[0],e=document.getElementById('coLocker');if(!e)return;e.innerHTML='';(OMNIVA_LOCKERS[city]||[]).forEach(x=>{const o=document.createElement('option');o.value=x;o.textContent=x;e.appendChild(o)});filterLockerOptions()}
function filterLockerOptions(){const q=norm(document.getElementById('coLockerSearch')?.value||''),sel=document.getElementById('coLocker');if(!sel)return;[...sel.options].forEach(o=>o.hidden=!!q&&!norm(o.textContent).includes(q))}
async function loadOmnivaLocations(){const cache=safeGet('sb_omniva_lv_locations_v1',null);if(cache&&cache.savedAt&&Date.now()-cache.savedAt<12*60*60*1000&&cache.data){OMNIVA_LOCKERS=cache.data;renderLockerCityOptions();return cache.data}try{const r=await fetch('/.netlify/functions/omniva-locations',{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('Omniva '+r.status);const data=await r.json();if(data?.cities&&Object.keys(data.cities).length){OMNIVA_LOCKERS=data.cities;safeSet('sb_omniva_lv_locations_v1',{savedAt:Date.now(),data:OMNIVA_LOCKERS});renderLockerCityOptions()}return OMNIVA_LOCKERS}catch(e){console.warn('Omniva dynamic locations unavailable',e);renderLockerCityOptions();return OMNIVA_LOCKERS}}
function updateCheckoutFields(){const d=document.getElementById('coDelivery')?.value||'omniva';document.getElementById('coLockerField').hidden=d!=='omniva';document.getElementById('coCourierField').hidden=d!=='courier';document.getElementById('coPay').querySelector('option[value="cash"]').disabled=d!=='courier';if(d!=='courier'&&document.getElementById('coPay').value==='cash')document.getElementById('coPay').value='stripe';const ship=d==='omniva'?2.99:4.99;document.getElementById('checkoutMiniShipping').textContent=euro(ship);renderCheckoutMini()}
function renderCheckoutMini(){const box=document.getElementById('checkoutMiniCart');if(!box)return;box.innerHTML=CART.map(i=>{const p=productById(i.id);return `<div class="mini-line"><span>${esc(p.name)} × ${i.qty}</span><strong>${euro(p.price*i.qty)}</strong></div>`}).join('');const d=document.getElementById('coDelivery')?.value||'omniva';const ship=d==='omniva'?2.99:4.99;document.getElementById('checkoutMiniTotal').textContent=euro(cartSubtotal()+ship);document.getElementById('checkoutCartCount').textContent=cartCount()}
function checkoutData(){const delivery=document.getElementById('coDelivery').value,pay=document.getElementById('coPay').value;const payload={name:document.getElementById('coName').value.trim(),email:document.getElementById('coEmail').value.trim(),delivery,payment:pay};if(delivery==='omniva')payload.destination=document.getElementById('coLocker').value;if(delivery==='courier')payload.destination=document.getElementById('coCourierAddress').value.trim();return payload}
function reviewOrder(){const terms=document.getElementById('coTerms');if(!terms||!terms.checked){toast(currentLang==='en'?'Confirm the purchase terms and delivery/withdrawal information.':currentLang==='ru'?'Подтвердите условия покупки и информацию о доставке/отказе.':'Apstiprini Pirkumu noteikumus un piegādes/atteikuma informāciju.');terms?.focus();return}const d=checkoutData();if(!d.name||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email)){toast(currentLang==='en'?'Enter your full name and a valid email.':currentLang==='ru'?'Введите имя и действительный e-mail.':'Aizpildi vārdu, uzvārdu un derīgu e-pastu.');return}if(d.delivery==='omniva'&&!d.destination){toast(currentLang==='en'?'Choose an Omniva city and parcel machine.':currentLang==='ru'?'Выберите город Omniva и постамат.':'Izvēlies Omniva pilsētu un pakomātu.');return}if(d.delivery==='courier'&&!d.destination){toast(currentLang==='en'?'Enter the courier delivery address.':currentLang==='ru'?'Введите адрес доставки курьером.':'Ievadi kurjera piegādes adresi.');return}document.getElementById('reviewDelivery').textContent=d.delivery==='omniva'?`Omniva · ${d.destination}`:'Kurjers · '+d.destination;document.getElementById('reviewPayment').textContent=d.payment==='cash'?(currentLang==='en'?'Cash to courier':currentLang==='ru'?'Наличными курьеру':'Skaidra nauda pie kurjera'):'Stripe Checkout';document.getElementById('reviewTotal').textContent=euro(cartSubtotal()+(d.delivery==='omniva'?2.99:4.99));document.getElementById('checkoutStep1').hidden=true;document.getElementById('checkoutStep2').hidden=false;document.getElementById('stepDot2').classList.add('active')}
function backToStep1(){clearCheckoutError();document.getElementById('checkoutStep2').hidden=true;document.getElementById('checkoutStep1').hidden=false}
function clearCheckoutError(){const el=document.getElementById('checkoutError');if(el){el.hidden=true;el.textContent=''}}
function showCheckoutError(message,code){const el=document.getElementById('checkoutError');const text=code?`${message} (${code})`:message;if(el){el.textContent=text;el.hidden=false;el.scrollIntoView({block:'nearest',behavior:'smooth'})}else toast(text)}
async function confirmOrder(){clearCheckoutError();const d=checkoutData();const items=CART.map(i=>({id:i.id,quantity:i.qty}));const btn=document.querySelector('#checkoutStep2 .checkout-primary');if(d.payment==='cash'){const order='SB-'+Math.floor(100000+Math.random()*899999);document.getElementById('checkoutStep2').hidden=true;document.getElementById('checkoutStep3').hidden=false;document.getElementById('stepDot3').classList.add('active');document.getElementById('checkoutStep3').querySelector('h3').textContent=currentLang==='en'?'Order accepted':currentLang==='ru'?'Заказ принят':'Pasūtījums pieņemts';document.getElementById('checkoutStep3').querySelector('p').textContent=currentLang==='en'?`Order No. ${order}. The courier will contact you before delivery. This is a demo confirmation; email delivery requires a server email service.`:currentLang==='ru'?`Заказ № ${order}. Курьер свяжется с вами перед доставкой. Это демо-подтверждение; отправка e-mail требует серверного почтового сервиса.`:`Pasūtījuma Nr. ${order}. Kurjers sazināsies pirms piegādes. Šis ir demo pasūtījuma apstiprinājums; e-pasta nosūtīšanai nepieciešams servera e-pasta pakalpojums.`;CART=[];saveCart();return}if(btn){btn.disabled=true;btn.setAttribute('aria-busy','true');btn.textContent=currentLang==='en'?'Opening Stripe Checkout…':currentLang==='ru'?'Открывается Stripe Checkout…':'Atver Stripe Checkout…'}try{const r=await fetch('/.netlify/functions/create-checkout-session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items,customer:{name:d.name,email:d.email},delivery:{method:d.delivery,destination:d.destination,payment:'stripe'}})});let data={};try{data=await r.json()}catch{}if(!r.ok||!data.url){const code=data.code||`HTTP_${r.status}`;throw Object.assign(new Error(data.error||'Stripe Checkout sesiju neizdevās izveidot.'),{code})}window.location.assign(data.url)}catch(err){console.error('Stripe Checkout error',err);showCheckoutError(err?.message||'Stripe Checkout neizdevās atvērt. Grozs nav zaudēts.',err?.code)}finally{if(btn){btn.disabled=false;btn.removeAttribute('aria-busy');btn.textContent=t('openStripe')}}}

function closeClerkAuth(){
 const modal=document.getElementById('clerkAuthModal');
 if(!modal)return;
 modal.classList.remove('open');modal.setAttribute('aria-hidden','true');
 try{if(clerk&&clerk.unmountSignIn)clerk.unmountSignIn(document.getElementById('clerkMount'));}catch{}
 try{if(clerk&&clerk.unmountSignUp)clerk.unmountSignUp(document.getElementById('clerkMount'));}catch{}
 document.getElementById('clerkMount').innerHTML='';
}
async function openClerkAuth(mode){
 const modal=document.getElementById('clerkAuthModal'),mount=document.getElementById('clerkMount'),warning=document.getElementById('clerkAuthOriginWarning');
 if(!modal||!mount)return;
 modal.classList.add('open');modal.setAttribute('aria-hidden','false');
 document.getElementById('clerkAuthTitle').textContent=mode==='signup'?'Reģistrēties':'Ienākt';
 document.getElementById('clerkAuthEyebrow').textContent=mode==='signup'?'Jauns konts':'Konts';
 document.getElementById('clerkAuthIntro').textContent=mode==='signup'?'Izveido savu SportaBiedrs.lv kontu un turpini lapā.':'Ienāc savā SportaBiedrs.lv kontā.';
 const isFile=location.protocol==='file:';
 warning.hidden=!isFile;
 if(isFile){mount.innerHTML='<div class="auth-file-state"><strong>Šis fails ir atvērts kā lokāls fails</strong><p>Aizver šo skatu un atver vietni caur <b>https://</b> vai palaid projektu ar <b>netlify dev</b>. Clerk, Google un CAPTCHA nevar pabeigt autentifikāciju no file://.</p><p>Atver publicēto <b>https://</b> adresi vai palaid projektu ar <b>netlify dev</b>.</p></div>';return}
 if(!clerk){mount.innerHTML='<div class="auth-file-state"><strong>Autentifikācijas modulis ielādējas…</strong><p>Uzgaidi dažas sekundes un mēģini vēlreiz.</p></div>';return}
 mount.innerHTML='';
 const appearance={variables:{colorPrimary:'#b84f24',colorText:'#211f1a',colorTextSecondary:'#746d60',borderRadius:'16px',fontFamily:'DM Sans, Arial, sans-serif'},elements:{card:'box-shadow:none;border:0;width:100%;',headerTitle:'font-family:DM Serif Display, Georgia, serif;font-size:28px;',socialButtonsBlockButton:'border:1px solid #ddd3bf;border-radius:12px;',formButtonPrimary:'background:#211f1a;border-radius:12px;',formFieldInput:'border:1px solid #cfc3ae;border-radius:12px;'}};
 const common={appearance,routing:'hash',oauthFlow:'popup'};
 try{
   if(mode==='signup') clerk.mountSignUp(mount,common);
   else clerk.mountSignIn(mount,common);
 }catch(e){console.error('Clerk mount',e);mount.innerHTML='<div class="auth-file-state"><strong>Neizdevās ielādēt autentifikāciju.</strong><p>Pārbaudi, vai Clerk Dashboard ir ieslēgts Google un e-pasta pieteikšanās un vai vietnes domēns ir atļauts.</p></div>';}
}
async function initClerk(){
 const si=document.getElementById('clerkSignInBtn'),su=document.getElementById('clerkSignUpBtn'),out=document.getElementById('clerkSignedOut'),inside=document.getElementById('clerkSignedIn'),ub=document.getElementById('clerkUserButton');
 if(!si||!su)return;
 let tries=0;while(!window.Clerk&&tries<150){await new Promise(r=>setTimeout(r,100));tries++}
 if(!window.Clerk){si.addEventListener('click',()=>toast('Clerk vēl ielādējas.'));su.addEventListener('click',()=>toast('Clerk vēl ielādējas.'));return}
 try{
   await window.Clerk.load({
  standardBrowser:true,
  ui:window.__internal_ClerkUICtor?{ClerkUI:window.__internal_ClerkUICtor}:undefined,
  appearance:{variables:{colorPrimary:'#b84f24',colorText:'#211f1a',fontFamily:'DM Sans, Arial, sans-serif',borderRadius:'16px'}}
});
   clerk=window.Clerk;
   const sync=()=>{const ok=!!clerk.isSignedIn;if(out)out.hidden=ok;if(inside)inside.hidden=!ok;if(ok&&ub&&!ub.dataset.mounted){ub.dataset.mounted='1';clerk.mountUserButton(ub,{appearance:{variables:{colorPrimary:'#b84f24'}}})}};
   clerk.addListener(sync);sync();
   si.addEventListener('click',()=>openClerkAuth('signin'));
   su.addEventListener('click',()=>openClerkAuth('signup'));
 }catch(e){console.error('Clerk',e);si.addEventListener('click',()=>openClerkAuth('signin'));su.addEventListener('click',()=>openClerkAuth('signup'));}
}


function initMobileNav(){
 const btn=document.getElementById('mobileNavToggle');
 const panel=document.getElementById('mobileNavPanel');
 if(!btn||!panel) return;
 const close=()=>{panel.hidden=true;btn.setAttribute('aria-expanded','false');btn.setAttribute('aria-label','Atvērt izvēlni')};
 const open=()=>{panel.hidden=false;btn.setAttribute('aria-expanded','true');btn.setAttribute('aria-label','Aizvērt izvēlni')};
 btn.addEventListener('click',()=>panel.hidden?open():close());
 panel.querySelectorAll('a').forEach(a=>a.addEventListener('click',close));
 window.addEventListener('resize',()=>{if(window.innerWidth>760) close()},{passive:true});
}

