function runInit(name,fn){try{fn()}catch(err){console.error(`[SportaBiedrs] ${name} failed`,err);const e=document.getElementById('appError');if(e){e.hidden=false;e.textContent=currentLang==='en'?`A section could not load. Please reload the page.`:currentLang==='ru'?`Не удалось загрузить раздел. Перезагрузите страницу.`:`Neizdevās ielādēt vienu no vietnes sadaļām. Pārlādē lapu.`;}}}
